function validate([root, limit]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let nodes = 0;
  for (let i = 0; i < root.length; i++) {
    // Entry i (after the root) is a child slot of an earlier node, so enough nodes must come before it.
    if (i > 0 && nodes * 2 < i) return 'root is not a valid level-order tree.';
    const v = root[i];
    if (v === null) continue;
    if (!Number.isInteger(v) || v < -100000 || v > 100000) return 'Node values are between -10^5 and 10^5.';
    nodes++;
  }
  if (nodes > 5000) return 'The tree has at most 5000 nodes.';
  if (!Number.isInteger(limit) || limit < -1000000000 || limit > 1000000000) return 'limit is between -10^9 and 10^9.';
  return null;
}

