function sufficientSubset(root, limit) {
  const prune = (node, sum) => {
    if (node === null) return null;
    sum += node.val;
    if (node.left === null && node.right === null) {
      return sum < limit ? null : node;
    }
    node.left = prune(node.left, sum);
    node.right = prune(node.right, sum);
    if (node.left === null && node.right === null) return null;
    return node;
  };
  return prune(root, 0);
}

