function sufficientSubset(root, limit) {
  // List every root-to-leaf path explicitly and keep each node that lies on a path reaching limit.
  const keep = new Set();
  const path = [];
  const walk = (node) => {
    path.push(node);
    if (!node.left && !node.right) {
      const total = path.reduce((acc, n) => acc + n.val, 0);
      if (total >= limit) for (const n of path) keep.add(n);
    }
    if (node.left) walk(node.left);
    if (node.right) walk(node.right);
    path.pop();
  };
  walk(root);
  // Copy the kept nodes into a fresh tree.
  const copy = (node) => {
    if (!node || !keep.has(node)) return null;
    return new TreeNode(node.val, copy(node.left), copy(node.right));
  };
  return copy(root);
}

