function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(700, 1000) : int(1, 9);
  const span = large || rand() < 0.4 ? 100000 : 6;
  const deep = rand() < 0.3;
  const root = { val: int(-span, span), left: null, right: null };
  // Each new node fills a free child slot; "deep" trees prefer the newest slots.
  const free = [[root, 'left'], [root, 'right']];
  for (let k = 1; k < n; k++) {
    const index = deep ? free.length - 1 - Math.floor(rand() * Math.min(free.length, 2)) : Math.floor(rand() * free.length);
    const [parent, side] = free.splice(index, 1)[0];
    const node = { val: int(-span, span), left: null, right: null };
    parent[side] = node;
    free.push([node, 'left'], [node, 'right']);
  }
  // Root-to-leaf sums help place limit where some paths pass and others fail.
  const sums = [];
  const collect = (node, sum) => {
    sum += node.val;
    if (!node.left && !node.right) sums.push(sum);
    if (node.left) collect(node.left, sum);
    if (node.right) collect(node.right, sum);
  };
  collect(root, 0);
  const r = rand();
  let limit;
  if (r < 0.05) limit = -1000000000;
  else if (r < 0.1) limit = 1000000000;
  else if (r < 0.75) limit = sums[Math.floor(rand() * sums.length)] + int(-1, 1);
  else limit = int(Math.min(...sums) - 5, Math.max(...sums) + 5);
  // Serialize level by level, then drop trailing nulls.
  const values = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    values.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (values[values.length - 1] === null) values.pop();
  return [values, limit];
}
